// C documentation
//
//	/** Match a whitespace: [ \t\n\r]. */
func char_is_space(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(2)) != 0))
}

// C documentation
//
//	/** Match an extended whitespace: [ \t\n\r\\v\\f], JSON5 whitespace. */
func char_is_space_ext(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)) != 0))
}

// C documentation
//
//	/** Match a JSON number: [.-+0-9]. */
func char_is_num(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(4)) != 0))
}

// C documentation
//
//	/** Match an ASCII character in string: ["\], [0x00-0x1F, 0x80-0xFF]. */
func char_is_ascii_skip(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(0)) != 0))
}

// C documentation
//
//	/** Match an ASCII character single-quoted: ['\], [0x00-0x1F, 0x80-0xFF]. */
func char_is_ascii_skip_sq(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(1)) != 0))
}

// C documentation
//
//	/** Match a trivia character: extended whitespace or comment. */
func char_is_trivia(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table1[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)|libc.Int32FromInt32(1)<<libc.Int32FromInt32(5)) != 0))
}

// C documentation
//
//	/** Match a line end character: [\r\n]. */
func char_is_eol(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table2[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(0)) != 0))
}

// C documentation
//
//	/** Match an extended line end character: [\r\n], JSON5 line terminator. */
func char_is_eol_ext(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table2[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(1)) != 0))
}

// C documentation
//
//	/** Match an identifier name start: [_$A-Za-z\], U+0080+. */
func char_is_id_start(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table2[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(2)) != 0))
}

// C documentation
//
//	/** Match an identifier name next: [_$A-Za-z0-9\], U+0080+. */
func char_is_id_next(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table2[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)) != 0))
}

// C documentation
//
//	/** Match an identifier name ASCII: [_$A-Za-z0-9]. */
func char_is_id_ascii(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table2[c])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(4)) != 0))
}

// C documentation
//
//	/** Match a sign: [+-] */
func char_is_sign(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(0)) != 0))
}

// C documentation
//
//	/** Match a none-zero digit: [1-9] */
func char_is_nonzero(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(2)) != 0))
}

// C documentation
//
//	/** Match a digit: [0-9] */
func char_is_digit(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(1)) != 0))
}

// C documentation
//
//	/** Match an exponent sign: [eE]. */
func char_is_exp(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)) != 0))
}

// C documentation
//
//	/** Match a floating point indicator: [.eE]. */
func char_is_fp(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(4)|libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)) != 0))
}

// C documentation
//
//	/** Match a digit or floating point indicator: [0-9.eE]. */
func char_is_digit_or_fp(tls *libc.TLS, d u8) (r uint8) {
	return libc.BoolUint8(!!(int32(char_table3[d])&(libc.Int32FromInt32(1)<<libc.Int32FromInt32(1)|libc.Int32FromInt32(1)<<libc.Int32FromInt32(4)|libc.Int32FromInt32(1)<<libc.Int32FromInt32(3)) != 0))
}

// C documentation
//
//	/** Match a JSON container: `{` or `[`. */
func char_is_ctn(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(int32(c)&int32(0xDF) == int32(0x5B)) /* '[': 0x5B, '{': 0x7B */
}

// C documentation
//
//	/** Convert ASCII letter to lowercase; valid only for [A-Za-z]. */
func char_to_lower(tls *libc.TLS, c u8) (r u8) {
	return uint8(int32(c) | int32(0x20))
}

// C documentation
//
//	/** Match UTF-8 byte order mask. */
func is_utf8_bom(tls *libc.TLS, cur uintptr) (r uint8) {
	return libc.BoolUint8(byte_load_3(tls, cur) == byte_load_3(tls, __ccgo_ts+1996))
}

// C documentation
//
//	/** Match UTF-16 byte order mask. */
func is_utf16_bom(tls *libc.TLS, cur uintptr) (r uint8) {
	return libc.BoolUint8(int32(byte_load_2(tls, cur)) == int32(byte_load_2(tls, __ccgo_ts+2000)) || int32(byte_load_2(tls, cur)) == int32(byte_load_2(tls, __ccgo_ts+2003)))
}

// C documentation
//
//	/** Match UTF-32 byte order mask, need length check to avoid zero padding. */
func is_utf32_bom(tls *libc.TLS, cur uintptr) (r uint8) {
	return libc.BoolUint8(byte_load_4(tls, cur) == byte_load_4(tls, __ccgo_ts+2006) || byte_load_4(tls, cur) == byte_load_4(tls, __ccgo_ts+2011))
}

// C documentation
//
//	/** Get the extended line end length. Used with `char_is_eol_ext`. */
func ext_eol_len(tls *libc.TLS, cur uintptr) (r usize) {
	if int32(*(*u8)(unsafe.Add(nil, cur))) < int32(0x80) {
		return uint64(1)
	}
	if int32(*(*u8)(unsafe.Add(nil, cur+1))) == int32(0x80) && (int32(*(*u8)(unsafe.Add(nil, cur+2))) == int32(0xA8) || int32(*(*u8)(unsafe.Add(nil, cur+2))) == int32(0xA9)) {
		return uint64(3)
	}
	return uint64(0)
}

// C documentation
//
//	/** Get the extended whitespace length. Used with `char_is_space_ext`. */
func ext_space_len(tls *libc.TLS, cur uintptr) (r usize) {
	var uni u32
	_ = uni
	if int32(*(*u8)(unsafe.Add(nil, cur))) < int32(0x80) {
		return uint64(1)
	} else {
		if int32(byte_load_2(tls, cur)) == int32(byte_load_2(tls, __ccgo_ts+2016)) {
			return uint64(2)
		} else {
			if int32(byte_load_2(tls, cur)) == int32(byte_load_2(tls, __ccgo_ts+2019)) {
				if int32(*(*u8)(unsafe.Add(nil, cur+2))) >= int32(0x80) && int32(*(*u8)(unsafe.Add(nil, cur+2))) <= int32(0x8A) {
					return uint64(3)
				}
				if int32(*(*u8)(unsafe.Add(nil, cur+2))) == int32(0xA8) || int32(*(*u8)(unsafe.Add(nil, cur+2))) == int32(0xA9) || int32(*(*u8)(unsafe.Add(nil, cur+2))) == int32(0xAF) {
					return uint64(3)
				}
			} else {
				uni = byte_load_3(tls, cur)
				if uni == byte_load_3(tls, __ccgo_ts+2022) || uni == byte_load_3(tls, __ccgo_ts+2026) || uni == byte_load_3(tls, __ccgo_ts+2030) || uni == byte_load_3(tls, __ccgo_ts+1996) {
					return uint64(3)
				}
			}
		}
	}
	return uint64(0)
}

