// C documentation
//
//	/** Load 4 hex characters to `u16`, return true on valid input. */
func hex_load_4(tls *libc.TLS, src uintptr, dst uintptr) (r uint8) {
	var c0, c1, c2, c3, t0, t1 u16
	_, _, _, _, _, _ = c0, c1, c2, c3, t0, t1
	c0 = uint16(hex_conv_table[*(*u8)(unsafe.Add(nil, src))])
	c1 = uint16(hex_conv_table[*(*u8)(unsafe.Add(nil, src+1))])
	c2 = uint16(hex_conv_table[*(*u8)(unsafe.Add(nil, src+2))])
	c3 = uint16(hex_conv_table[*(*u8)(unsafe.Add(nil, src+3))])
	t0 = uint16(int32(c0)<<libc.Int32FromInt32(8) | int32(c2))
	t1 = uint16(int32(c1)<<libc.Int32FromInt32(8) | int32(c3))
	*(*u16)(unsafe.Add(nil, dst)) = uint16(int32(t0)<<libc.Int32FromInt32(4) | int32(t1))
	return libc.BoolUint8((int32(t0)|int32(t1))&int32(libc.Uint16FromInt32(0xF0F0)) == 0)
}

// C documentation
//
//	/** Load 2 hex characters to `u8`, return true on valid input. */
func hex_load_2(tls *libc.TLS, src uintptr, dst uintptr) (r uint8) {
	var c0, c1 u8
	_, _ = c0, c1
	c0 = hex_conv_table[*(*u8)(unsafe.Add(nil, src))]
	c1 = hex_conv_table[*(*u8)(unsafe.Add(nil, src+1))]
	*(*u8)(unsafe.Add(nil, dst)) = uint8(int32(c0)<<libc.Int32FromInt32(4) | int32(c1))
	return libc.BoolUint8((int32(c0)|int32(c1))&int32(0xF0) == 0)
}

// C documentation
//
//	/** Match a hexadecimal numeric character: [0-9a-fA-F]. */
func char_is_hex(tls *libc.TLS, c u8) (r uint8) {
	return libc.BoolUint8(int32(hex_conv_table[c]) != int32(0xF0))
}

/*==============================================================================
 * MARK: - UTF8 Validation (Private)
 * Each Unicode code point is encoded using 1 to 4 bytes in UTF-8.
 * Validation is performed using a 4-byte mask and pattern-based approach,
 * which requires the input data to be padded with four zero bytes at the end.
 *============================================================================*/

/* Macro for concatenating four u8 into a u32 and keeping the byte order. */

// C documentation
//
//	/*
//	 1-byte sequence (U+0000 to U+007F)
//	 bit min        [.......0] (U+0000)
//	 bit max        [.1111111] (U+007F)
//	 bit mask       [x.......] (80)
//	 bit pattern    [0.......] (00)
//	 */
