var utf8_seq_b1_patt = uint32(0x00000000)

// C documentation
//
//	/*
//	 2-byte sequence (U+0080 to U+07FF)
//	 bit min        [......10 ..000000] (U+0080)
//	 bit max        [...11111 ..111111] (U+07FF)
//	 bit mask       [xxx..... xx......] (E0 C0)
//	 bit pattern    [110..... 10......] (C0 80)
//	 bit require    [...xxxx. ........] (1E 00)
//	 */
var utf8_seq_b2_mask = uint32(0x0000C0E0)

var utf8_seq_b2_patt = uint32(0x000080C0)

var utf8_seq_b2_requ = uint32(0x0000001E)

// C documentation
