func write_u32_len_8(tls *libc.TLS, val u32, buf uintptr) (r uintptr) {
	var aa, aabb, bb, cc, ccdd, dd u32
	_, _, _, _, _, _ = aa, aabb, bb, cc, ccdd, dd                                           /* 8 digits: aabbccdd */
	aabb = uint32(uint64(val) * libc.Uint64FromInt32(109951163) >> libc.Int32FromInt32(40)) /* (val / 10000) */
	ccdd = val - aabb*uint32(10000)                                                         /* (val % 10000) */
	aa = aabb * uint32(5243) >> int32(19)                                                   /* (aabb / 100) */
	cc = ccdd * uint32(5243) >> int32(19)                                                   /* (ccdd / 100) */
	bb = aabb - aa*uint32(100)                                                              /* (aabb % 100) */
	dd = ccdd - cc*uint32(100)                                                              /* (ccdd % 100) */
	byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(aa*uint32(2)))
	byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2)))
	byte_copy_2(tls, buf+uintptr(4), uintptr(unsafe.Pointer(&digit_table))+uintptr(cc*uint32(2)))
	byte_copy_2(tls, buf+uintptr(6), uintptr(unsafe.Pointer(&digit_table))+uintptr(dd*uint32(2)))
	return buf + uintptr(8)
}

func write_u32_len_4(tls *libc.TLS, val u32, buf uintptr) (r uintptr) {
	var aa, bb u32
	_, _ = aa, bb                        /* 4 digits: aabb */
	aa = val * uint32(5243) >> int32(19) /* (val / 100) */
	bb = val - aa*uint32(100)            /* (val % 100) */
	byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(aa*uint32(2)))
	byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2)))
	return buf + uintptr(4)
}

func write_u32_len_1_to_8(tls *libc.TLS, val u32, buf uintptr) (r uintptr) {
	var aa, aabb, bb, bbcc, cc, ccdd, dd, lz u32
	_, _, _, _, _, _, _, _ = aa, aabb, bb, bbcc, cc, ccdd, dd, lz
	if val < uint32(100) { /* 1-2 digits: aa */
		lz = libc.BoolUint32(val < uint32(10)) /* leading zero: 0 or 1 */
		byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(val*uint32(2))+uintptr(lz))
		buf = buf - uintptr(lz)
		return buf + uintptr(2)
	} else {
		if val < uint32(10000) { /* 3-4 digits: aabb */
			aa = val * uint32(5243) >> int32(19)  /* (val / 100) */
			bb = val - aa*uint32(100)             /* (val % 100) */
			lz = libc.BoolUint32(aa < uint32(10)) /* leading zero: 0 or 1 */
			byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(aa*uint32(2))+uintptr(lz))
			buf = buf - uintptr(lz)
			byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2)))
			return buf + uintptr(4)
		} else {
			if val < uint32(1000000) { /* 5-6 digits: aabbcc */
				aa = uint32(uint64(val) * libc.Uint64FromInt32(429497) >> libc.Int32FromInt32(32)) /* (val / 10000) */
				bbcc = val - aa*uint32(10000)                                                      /* (val % 10000) */
				bb = bbcc * uint32(5243) >> int32(19)                                              /* (bbcc / 100) */
				cc = bbcc - bb*uint32(100)                                                         /* (bbcc % 100) */
				lz = libc.BoolUint32(aa < uint32(10))                                              /* leading zero: 0 or 1 */
				byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(aa*uint32(2))+uintptr(lz))
				buf = buf - uintptr(lz)
				byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2)))
				byte_copy_2(tls, buf+uintptr(4), uintptr(unsafe.Pointer(&digit_table))+uintptr(cc*uint32(2)))
				return buf + uintptr(6)
			} else { /* 7-8 digits: aabbccdd */
				aabb = uint32(uint64(val) * libc.Uint64FromInt32(109951163) >> libc.Int32FromInt32(40)) /* (val / 10000) */
				ccdd = val - aabb*uint32(10000)                                                         /* (val % 10000) */
				aa = aabb * uint32(5243) >> int32(19)                                                   /* (aabb / 100) */
				cc = ccdd * uint32(5243) >> int32(19)                                                   /* (ccdd / 100) */
				bb = aabb - aa*uint32(100)                                                              /* (aabb % 100) */
				dd = ccdd - cc*uint32(100)                                                              /* (ccdd % 100) */
				lz = libc.BoolUint32(aa < uint32(10))                                                   /* leading zero: 0 or 1 */
				byte_copy_2(tls, buf+uintptr(0), uintptr(unsafe.Pointer(&digit_table))+uintptr(aa*uint32(2))+uintptr(lz))
				buf = buf - uintptr(lz)
				byte_copy_2(tls, buf+uintptr(2), uintptr(unsafe.Pointer(&digit_table))+uintptr(bb*uint32(2)))
				byte_copy_2(tls, buf+uintptr(4), uintptr(unsafe.Pointer(&digit_table))+uintptr(cc*uint32(2)))
				byte_copy_2(tls, buf+uintptr(6), uintptr(unsafe.Pointer(&digit_table))+uintptr(dd*uint32(2)))
				return buf + uintptr(8)
			}
		}
	}
	return r
}

