// C documentation
//
//	/** Divide a number by power of 10. */
func div_pow10(tls *libc.TLS, num u64, exp u32, div uintptr, mod uintptr, p10 uintptr) {
	bp := tls.Alloc(16)
	defer tls.Free(16)
	var m div_pow10_magic
	var _ /* hi at bp+0 */ u64
	var _ /* lo at bp+8 */ u64
	_ = m
	m = div_pow10_table[exp]
	u128_mul(tls, num>>m.Fshr1, m.Fmul, bp, bp+8)
	*(*u64)(unsafe.Add(nil, div)) = *(*u64)(unsafe.Add(nil, bp)) >> m.Fshr2
	*(*u64)(unsafe.Add(nil, mod)) = num - *(*u64)(unsafe.Add(nil, div))*m.Fp10
	*(*u64)(unsafe.Add(nil, p10)) = m.Fp10
}

